import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.DdtnLau3.js";const c=JSON.parse('{"title":"开始使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/guide/index.md"}'),i={name:"zh/guide/index.md"};function n(s,e,h,p,d,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h1><p>一个 Linux 应用提供 <strong>Core</strong>、网页工作台、<strong>Admin</strong> 管理和首次设置。其他 Linux 或 Windows 电脑直接通过服务器 IP 打开浏览器使用，CLI 是独立可选工具。</p><ol><li><a href="/piwork/zh/guide/quick-start.html">一键启动</a>：运行一个 Docker 容器，通过私有设置链接创建管理员并确认密码，正常登录后在 <strong>Admin → Quick setup</strong> 填写或选择模型。</li><li><a href="/piwork/zh/guide/installation.html">安装与部署</a>：平台、端口、持久化、可选 Compose、故障处理及恢复。</li><li><a href="/piwork/zh/guide/first-work.html">第一个 Work</a>：等待准备完成，点击 <strong>Open workbench</strong> 后创建 Work，使用 Chat、Files 和 Service。</li></ol><p>已有安装可直接打开工作台；管理员从 <strong>Overview → Quick setup</strong> 重新配置。<strong>Save and continue</strong> 顺序保存模型与 CoreRuntime，Test 显式可选，Agent 镜像由服务端发行版本固定，不需要填写。</p><p>需要开发应用？<a href="/piwork/zh/guide/web-development.html">Web 开发指南</a>介绍默认环境、持久化和升级。模型协议、Key、Test 和 Thinking 见 <a href="/piwork/zh/guide/ai-models.html">AI 模型</a>。</p><h2 id="当前支持范围" tabindex="-1">当前支持范围 <a class="header-anchor" href="#当前支持范围" aria-label="Permalink to &quot;当前支持范围&quot;">​</a></h2><p>镜像面向 Linux amd64；Core 使用 Linux rootful Docker Engine 28+ 和同机 Unix socket。网页工作台可从远程浏览器访问，无需域名、DNS、WSL 或客户端 CLI。主站默认 7171，Service 入口为 17891–17954，7172 仅供内部 Agent RPC。Compose 2.24+ 仅用于可选 Compose 部署。</p><p><a href="/piwork/zh/spec/">规范概览</a>记录源码及镜像来源；应用示例见 <a href="/piwork/zh/demo/kanban.html">Kanban Work</a>。</p><p><a href="/piwork/zh/guide/quick-start.html">Quick Start</a> 使用统一应用与网页引导，CLI 可选；原生构建与管理员操作见独立导航。</p>',9)])])}const m=t(i,[["render",n]]);export{c as __pageData,m as default};
